-- ============================================================
-- SEED EXT 6: Módulo 09 — Conditional Type 1 (ex 229-300)
-- Tópicos: Type 1 em análise política avançada, variações modais,
-- conectivos condicionais formais, contextos científicos e TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'conditional-1';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo conditional-1 não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Type 1 em análise de política pública avançada
  (cid,71,229,'gap_fill','If _____ government _____ (fail) to _____ (address) _____ structural deficit within _____ next fiscal cycle, _____ credit rating agencies _____ (likely/downgrade) _____ sovereign debt, _____ (trigger) _____ cascade of _____ borrowing cost _____ increases.','the / fails / address / the / the / will likely downgrade / its / triggering / a / cascade / borrowing',NULL,'Type 1 + "will likely" + participial cascade consequence.','hard'),
  (cid,71,230,'gap_fill','Provided that _____ reform _____ (implement/passive) as _____ legislated, _____ projected _____ efficiency gains _____ (materialize) within _____ three-year _____ horizon, _____ (give) _____ government _____ fiscal space it _____ (need) to _____ (sustain) _____ investment in _____ priority _____ areas.','the / is implemented / the / legislated / the / projected / will materialize / a / three-year / giving / the / the / needs / sustain / the / priority',NULL,'"Provided that" + Type 1 + participial consequence "giving."','hard'),
  (cid,71,231,'gap_fill','Unless _____ parties _____ (agree) on _____ enforcement mechanism before _____ summit _____ (conclude), _____ agreement _____ (likely/function) as _____ statement of _____ intent rather than _____ binding _____ commitment.','the / agree / an / the / concludes / the / will likely function / a / intent / a / binding',NULL,'"Unless" + Type 1 + "will likely function as."','medium'),
  (cid,71,232,'multiple_choice','Which Type 1 conditional MOST effectively expresses a policy contingency?','If the central bank raises interest rates by more than 50 basis points, the housing market will contract significantly.','["If the central bank raised rates, the housing market would contract.","If the central bank raises interest rates by more than 50 basis points, the housing market will contract significantly.","If the central bank had raised rates, the housing market would have contracted.","If the central bank raises rates, the housing market contracts."]','Type 1: "raises" (present simple) + "will contract" (future) = real, specific contingency. Type 2 would express hypothetical.','easy'),
  (cid,71,233,'gap_fill','Should _____ pilot _____ (demonstrate) _____ projected _____ outcomes, _____ government _____ (scale) _____ program nationally, _____ (create) _____ estimated 50,000 _____ new _____ positions within _____ first _____ two years of _____ rollout.','the / demonstrate / the / projected / the / will scale / the / creating / an / new / positions / the / first / the',NULL,'"Should" inverted conditional (formal) + "will scale" + participial consequence.','hard'),
  (cid,71,234,'gap_fill','As long as _____ fiscal _____ consolidation _____ (proceed) at _____ pace consistent with _____ growth _____ objectives, _____ international _____ partners _____ (continue) to _____ (provide) _____ technical and _____ financial _____ support _____ (need/passive) to _____ (sustain) _____ reform _____ program.','the / fiscal / consolidation / proceeds / a / the / growth / the / international / will continue / provide / the / technical / financial / needed / sustain / the / reform',NULL,'"As long as" + Type 1 formal conditional for international support commitment.','hard'),
  (cid,71,235,'gap_fill','If _____ evidence _____ (continue) to _____ (accumulate) at _____ current _____ rate, _____ scientific consensus _____ (shift) within _____ decade in ways that _____ (require) _____ fundamental _____ revision of _____ existing _____ regulatory _____ frameworks.','the / continues / accumulate / the / current / the / will shift / a / will require / a / fundamental / the / existing / regulatory',NULL,'Type 1 for evidence-based prediction about scientific consensus shift.','medium'),
  (cid,71,236,'gap_fill','Only if _____ all _____ major _____ emitters _____ (participate) in _____ agreement _____ (the emissions reductions/sufficient/be) to _____ (prevent) _____ most _____ severe _____ consequences of _____ climate _____ change — _____ partial _____ participation _____ (not/enough/prove).','all / major / emitters / participate / the / will the emissions reductions be sufficient / prevent / the / most / severe / the / climate / partial / will not prove sufficient',NULL,'"Only if" inversion + Type 1 for multilateral necessity argument.','hard'),

  -- BLOCK 72: Type 1 com variações modais (may, might, can, should)
  (cid,72,237,'gap_fill','If _____ implementation _____ (proceed) as _____ planned, _____ results _____ (may/exceed) _____ initial _____ projections — though _____ depends critically on _____ (whether) _____ external _____ conditions _____ (remain) _____ favorable.','the / proceeds / planned / the / may exceed / the / initial / this / whether / the / remain / favorable',NULL,'Type 1 + "may exceed" (weaker certainty) + dependent clause.','medium'),
  (cid,72,238,'gap_fill','If _____ monitoring _____ data _____ (show) _____ significant _____ deviations from _____ baseline, _____ program _____ managers _____ (should/convene) _____ emergency _____ review _____ (assess) _____ corrective _____ options _____ available.','the / monitoring / shows / the / significant / the / the / program / should convene / an / emergency / to assess / the / corrective / options',NULL,'Type 1 + "should convene" (obligation) + infinitive of purpose.','medium'),
  (cid,72,239,'gap_fill','If _____ technology _____ (mature) sufficiently over _____ next _____ five years, it _____ (can/deploy/passive) at _____ commercial _____ scale and _____ (begin) to _____ (displace) _____ fossil _____ fuel _____ alternatives in _____ key _____ markets.','the / matures / the / next / five / can be deployed / commercial / begin / displace / fossil / fuel / alternatives / key / markets',NULL,'Type 1 + "can be deployed" + infinitive chain for technology deployment.','medium'),
  (cid,72,240,'multiple_choice','Which modal variation of Type 1 conditional is MOST APPROPRIATE for a formal policy recommendation?','If the committee approves the proposal, the secretariat should begin procurement immediately.','["If the committee approves the proposal, the secretariat will begin procurement immediately.","If the committee approves the proposal, the secretariat should begin procurement immediately.","If the committee approves the proposal, the secretariat may begin procurement immediately.","If the committee approves the proposal, the secretariat can begin procurement immediately."]','"Should begin" = recommendation/obligation in result clause. "Will" = certainty. "May" = possibility. "Can" = ability. "Should" most appropriate for formal procedural recommendation.','medium'),
  (cid,72,241,'gap_fill','If _____ initial _____ results _____ (not/promising/prove), _____ funding _____ (may/redirect/passive) to _____ more _____ productive _____ lines of _____ inquiry rather than _____ (commit) to _____ full _____ second _____ phase.','the / results / do not prove promising / funding / may be redirected / more / productive / lines / inquiry / committing / a / full / second',NULL,'Type 1 + "may be redirected" + gerund alternative.','medium'),
  (cid,72,242,'gap_fill','If _____ bilateral _____ trade _____ tensions _____ (escalate) further, _____ third-party _____ mediators _____ (might/need) to _____ (intervene) before _____ dispute _____ (reach) _____ point where _____ resolution _____ (become) _____ significantly _____ more _____ difficult.','the / bilateral / trade / escalate / further / third-party / might need / intervene / the / reaches / a / resolution / becomes / significantly / more / difficult',NULL,'Type 1 + "might need to intervene" for diplomatic contingency.','hard'),
  (cid,72,243,'gap_fill','Should _____ appellate _____ court _____ (uphold) _____ lower _____ court''s _____ ruling, _____ precedent _____ (set) _____ (significantly/alter) _____ regulatory _____ landscape across _____ entire _____ sector.','the / appellate / court / uphold / the / lower / the / will set a precedent / significantly altering / the / regulatory / the / entire',NULL,'"Should" inversion + "will set a precedent" + participial consequence.','hard'),
  (cid,72,244,'gap_fill','If _____ negotiating _____ parties _____ (reach) _____ agreement in _____ principle during _____ current _____ round, _____ technical _____ working _____ groups _____ (can/begin) _____ (draft) _____ implementing _____ provisions _____ (finalize/passive) before _____ next _____ ministerial.','the / negotiating / reach / an / principle / the / current / the / technical / working / can begin / drafting / the / implementing / to be finalized / the / next / ministerial',NULL,'Type 1 + "can begin drafting" + passive infinitive for finalization.','hard'),

  -- BLOCK 73: Type 1 com unless, provided that, as long as, only if
  (cid,73,245,'gap_fill','_____ (Unless) _____ signatory _____ states _____ (ratify) _____ convention within _____ 24-month _____ window, _____ provisional _____ arrangements _____ (lapse) and _____ negotiations _____ (need) to _____ (restart) from _____ scratch.','Unless / the / signatory / ratify / the / convention / the / the / will lapse / negotiations / will need / restart / scratch',NULL,'"Unless" + Type 1 + double consequence for ratification deadline.','medium'),
  (cid,73,246,'gap_fill','Provided _____ that _____ (adequate/fund) _____ (secure/passive) within _____ current _____ budgetary _____ cycle, _____ construction _____ (commence) in _____ first _____ quarter and _____ (complete/passive) _____ (well/within) _____ original _____ timeline.','Provided / that / adequate / funding / is secured / the / current / budgetary / the / will commence / the / will be completed / well within / the / original',NULL,'"Provided that" + Type 1 passive + double future consequence.','medium'),
  (cid,73,247,'gap_fill','As _____ long as _____ inflation _____ (remain) within _____ target _____ band, _____ central _____ bank _____ (not/need) to _____ (tighten) _____ monetary _____ policy _____ (further) and _____ (can/maintain) _____ accommodative _____ stance that _____ (support) _____ growth.','As / long / remains / the / target / the / central / will not need / tighten / monetary / policy / further / can maintain / the / that / supports',NULL,'"As long as" + Type 1 + negative + "can maintain" for monetary policy contingency.','medium'),
  (cid,73,248,'multiple_choice','Which formal conditional connective is MOST PRECISE for a legal contract?','The supplier shall deliver the goods on the agreed date provided that the buyer transfers the deposit no later than five business days in advance.','["If the buyer transfers the deposit, the supplier shall deliver the goods on time.","Unless the buyer transfers the deposit, the goods will not be delivered.","The supplier shall deliver the goods on the agreed date provided that the buyer transfers the deposit no later than five business days in advance.","As long as the buyer pays, the supplier will deliver."]','"Provided that" is the most formal and legally precise conditional connective, specifying exact conditions.','medium'),
  (cid,73,249,'gap_fill','Only _____ if _____ all _____ conditions _____ (meet/passive) simultaneously _____ (the initiative/proceed) to _____ implementation phase — _____ failure to _____ (satisfy) any _____ single _____ criterion _____ (trigger) _____ comprehensive _____ review.','Only / if / all / conditions / are met / will the initiative proceed / the / failure / satisfy / single / will trigger / a / comprehensive',NULL,'"Only if" inversion + Type 1 for strict multi-condition gate.','hard'),
  (cid,73,250,'gap_fill','In _____ event that _____ primary _____ contractor _____ (fail) to _____ (meet) _____ performance _____ benchmarks, _____ agreement _____ (provides) that _____ client _____ (may/engage) _____ alternative _____ supplier without _____ (incur) any _____ financial _____ penalty.','the / event / the / primary / contractor / fails / meet / the / performance / the / provides / the / may engage / an / alternative / incurring / financial',NULL,'"In the event that" + Type 1 + "may engage" + negative gerund.','hard'),
  (cid,73,251,'gap_fill','Assuming _____ that _____ technical _____ specifications _____ (confirm/passive) by _____ independent _____ audit, _____ procurement _____ committee _____ (authorize) _____ purchase without _____ (require) _____ further _____ competitive _____ tender.','Assuming / that / the / technical / are confirmed / an / independent / the / procurement / will authorize / the / requiring / further / competitive',NULL,'"Assuming that" + Type 1 + "will authorize" + negative gerund.','hard'),
  (cid,73,252,'gap_fill','On _____ condition that _____ recipient _____ government _____ (maintain) _____ macroeconomic _____ stability and _____ (meet) _____ agreed _____ structural _____ benchmarks, _____ disbursements _____ (continue) on _____ quarterly _____ schedule _____ (set out) in _____ financing _____ agreement.','On / condition / the / recipient / maintains / macroeconomic / meets / the / agreed / structural / the / will continue / a / quarterly / set out / the / financing',NULL,'"On condition that" + Type 1 + "will continue" for conditional disbursement.','hard'),

  -- BLOCK 74: Type 1 em contextos científicos e de pesquisa
  (cid,74,253,'gap_fill','If _____ replication _____ studies _____ (confirm) _____ original _____ findings, _____ result _____ (establish) _____ robust _____ evidence base for _____ clinical _____ application — if they _____ (fail) to _____ (do) so, _____ (need) to _____ (return) to _____ drawing _____ board.','the / replication / confirm / the / original / the / will establish / a / robust / for / clinical / fail / do / we will need / return / the / drawing',NULL,'Type 1 binary research outcome structure.','medium'),
  (cid,74,254,'gap_fill','If _____ model''s _____ predictions _____ (not/match) _____ observed _____ data within _____ acceptable _____ margin of _____ error, _____ underlying _____ assumptions _____ (need) to _____ (revise/passive) and _____ model _____ (recalibrate/passive) before _____ further _____ analysis _____ (proceed).','the / predictions / do not match / the / observed / the / acceptable / the / the / underlying / will need / be revised / the / will be recalibrated / further / analysis / proceeds',NULL,'Type 1 + "will need to be revised/recalibrated" for scientific model revision.','hard'),
  (cid,74,255,'gap_fill','Should _____ Phase 2 _____ trials _____ (demonstrate) _____ acceptable _____ safety _____ profile, _____ compound _____ (advance) to _____ Phase 3 _____ efficacy _____ trials, which _____ (enroll) _____ substantially _____ larger _____ patient _____ cohort.','the / Phase / trials / demonstrate / an / acceptable / safety / the / will advance / Phase / efficacy / will enroll / a / substantially / larger / patient',NULL,'"Should" + Type 1 for clinical trial progression gate.','medium'),
  (cid,74,256,'multiple_choice','Which Type 1 conditional BEST expresses a scientific hypothesis?','If the intervention increases dopamine levels, the subjects will demonstrate improved performance on the attention tasks.','["If the intervention increased dopamine, subjects would show improved performance.","If the intervention increases dopamine levels, the subjects will demonstrate improved performance on the attention tasks.","If the intervention had increased dopamine, subjects would have shown improved performance.","When the intervention increases dopamine, subjects demonstrate improved performance."]','Type 1: "increases" + "will demonstrate" = testable real hypothesis about expected outcome.','easy'),
  (cid,74,257,'gap_fill','If _____ (the/sample/size) _____ (prove) _____ too _____ small to _____ (detect) _____ effect of _____ interest, _____ study _____ (need) to _____ (power/passive) more _____ adequately before _____ conclusions _____ (draw/passive) about _____ null _____ hypothesis.','the sample size / proves / too / small / detect / the / interest / the / will need / be powered / adequately / conclusions / can be drawn / the / null',NULL,'Type 1 for statistical power contingency in research methodology.','hard'),
  (cid,74,258,'gap_fill','If _____ peer _____ review _____ process _____ (identify) _____ significant _____ methodological _____ concerns, _____ authors _____ (require/passive) to _____ (address) them _____ (comprehensively) before _____ manuscript _____ (accept/passive) for _____ publication.','the / peer / review / identifies / significant / methodological / the / will be required / address / comprehensively / the / is accepted / publication',NULL,'Type 1 passive "will be required" for peer review contingency.','medium'),
  (cid,74,259,'gap_fill','Should _____ the _____ analysis _____ (reveal) _____ statistically _____ significant _____ correlation, _____ finding _____ (warrant) further _____ investigation of _____ causal _____ mechanisms that _____ (might/explain) _____ observed _____ relationship.','the / analysis / reveal / a / statistically / significant / the / will warrant / further / the / causal / might explain / the / observed',NULL,'"Should" inversion + "will warrant" for cautious research implication statement.','medium'),
  (cid,74,260,'gap_fill','If _____ (external/valid) _____ (establish/passive) through _____ cross-site _____ replication, _____ intervention _____ (candidate/become/passive) for _____ inclusion in _____ evidence-based _____ guidelines _____ (govern) _____ clinical _____ practice in _____ field.','external validity / is established / cross-site / the / will become a candidate / the / evidence-based / governing / clinical / the',NULL,'Type 1 + "will become a candidate" for evidence-based guideline inclusion.','hard'),

  -- BLOCK 75: TOEFL Reading com Type 1
  (cid,75,261,'multiple_choice','[TOEFL Reading] "If current deforestation rates continue, the Amazon will lose 25% of its remaining forest cover within two decades." This conditional expresses:','A real, evidence-based projection about a likely future outcome if present trends persist.','["An impossible hypothetical","A past event","A real, evidence-based projection about a likely future outcome if present trends persist.","A universal scientific law"]','Type 1 = real condition + likely future outcome. "Current rates continue" is a real, observable possibility.','easy'),
  (cid,75,262,'gap_fill','[TOEFL Reading] "If _____ international _____ community _____ (not/act) decisively within _____ next _____ decade, _____ window for _____ preventing _____ most catastrophic _____ outcomes _____ (close) permanently." Best forms?','the / international / does not act / the / next / the / the / will close',NULL,'Type 1 with negative + "will close" for climate window argument.','medium'),
  (cid,75,263,'gap_fill','[TOEFL Reading] "Provided _____ that _____ investment _____ in _____ infrastructure _____ (maintain/passive) at _____ current _____ levels, _____ productivity _____ gains _____ (continue) to _____ accumulate and _____ (eventually/offset) _____ initial _____ costs." Best forms?','Provided / that / investment / in / infrastructure / is maintained / the / current / productivity / will continue / accumulate / eventually offset / the / initial',NULL,'"Provided that" + Type 1 for infrastructure investment argument.','medium'),
  (cid,75,264,'multiple_choice','[TOEFL Reading] "If governments fail to coordinate their responses, the crisis will spread beyond the region." The word "fail" in this context is:','Present simple, marking the condition as a real possibility rather than a hypothetical.','["Past tense","A modal verb","Present simple, marking the condition as a real possibility rather than a hypothetical.","Future tense"]','Type 1 requires present simple in the if-clause for real/open conditions.','easy'),
  (cid,75,265,'gap_fill','[TOEFL Reading] "As long as _____ regulatory _____ framework _____ (remain) _____ predictable, _____ private _____ sector _____ (continue) to _____ (invest) in _____ renewable _____ infrastructure at _____ pace _____ (sufficient) to _____ (meet) _____ transition _____ goals." Best forms?','the / regulatory / remains / predictable / the / private / will continue / invest / renewable / a / sufficient / meet / the / transition',NULL,'"As long as" + Type 1 for regulatory predictability investment argument.','medium'),
  (cid,75,266,'gap_fill','[TOEFL Reading] "Should _____ trials _____ (confirm) _____ safety and _____ efficacy of _____ treatment, _____ regulatory _____ pathway _____ (expedite/passive) and _____ approval _____ (potentially/grant/passive) within _____ compressed _____ timeframe." Best forms?','the / trials / confirm / the / the / the / will be expedited / approval / will potentially be granted / a / compressed',NULL,'"Should" inversion + Type 1 passive double consequence for clinical approval pathway.','hard'),
  (cid,75,267,'gap_fill','[TOEFL Reading] "Unless _____ structural _____ reforms _____ (accompany) _____ fiscal _____ adjustment, _____ (austerity/risk) _____ (trap) _____ economy in _____ low-growth _____ equilibrium from which _____ (difficult) to _____ (escape)." Best forms?','structural / reforms / accompany / the / fiscal / austerity risks / trapping / the / a / it will be difficult / escape',NULL,'"Unless" + Type 1 + gerund risk for structural reform necessity.','hard'),
  (cid,75,268,'gap_fill','[TOEFL Reading] "If _____ technology _____ (not/develop/passive) fast enough to _____ (meet) _____ demand, _____ energy _____ transition _____ (stall) and _____ emissions _____ (not/fall) at _____ rate _____ (require/passive) to _____ (limit) _____ warming to _____ acceptable levels." Best forms?','the / technology / is not developed / meet / the / the / energy / will stall / emissions / will not fall / the / required / limit / warming / acceptable',NULL,'Type 1 negative passive "is not developed" + double negative consequence.','hard'),

  -- BLOCK 76: TOEFL Speaking com Type 1
  (cid,76,269,'production','[TOEFL Speaking — 45s] Summarize what a reading says will happen if an international agreement is not reached.','',NULL,'The reading argues that if the international community fails to reach a binding agreement at the upcoming summit, the consequences will be severe and difficult to reverse. According to the reading, if participating nations do not commit to specific emissions reductions with enforceable targets, the temperature increase will exceed 2 degrees Celsius before the end of the century, triggering a cascade of impacts including sea level rise, extreme weather events, and agricultural disruption that will affect billions of people. The reading also notes that if the major emitters do not coordinate their policies, carbon leakage will undermine the effectiveness of any unilateral measures individual countries adopt, meaning that ambitious domestic action will not produce the global reductions required. Furthermore, the reading argues that if the agreement fails to include adequate financing for developing countries, those nations will face impossible choices between development and decarbonization that will make their participation in the global effort unsustainable. The reading concludes that if these conditions are not met at this summit, the window for orderly, cost-effective transition will close, and the disruption of a disorderly transition will prove far more costly.','hard'),
  (cid,76,270,'production','[TOEFL Speaking — 45s] A professor discusses what will happen if automation displaces workers faster than new jobs emerge.','',NULL,'The professor argues that if automation displaces workers significantly faster than new employment opportunities emerge — which she describes as the central risk in the current technological transition — the social and political consequences will be severe. She explains that if large numbers of workers lose their jobs to automation and cannot find comparable employment, consumer demand will fall, potentially triggering the kind of demand-side recession that is very difficult to escape through conventional monetary policy. If displaced workers are concentrated in particular regions or demographic groups, the political polarization that is already visible in many high-income countries will intensify, creating pressure for policy responses that may slow technological adoption without providing effective support for those displaced. The professor emphasizes that if governments do not invest substantially in retraining programs and redesign social insurance to cover workers in non-standard employment, the adjustment will generate levels of hardship that democratic systems will struggle to sustain. She concludes that none of these outcomes are inevitable — if policy responds adequately, the transition can be managed — but that if the assumption that markets will automatically generate sufficient new employment proves wrong, the costs of inadequate preparation will be very high.','hard'),
  (cid,76,271,'production','[TOEFL Speaking — 60s] Discuss what will happen if a country pursues economic development without environmental safeguards, using Type 1 conditionals throughout.','',NULL,'If a country pursues economic development without adequate environmental safeguards, it will generate growth in the short term but will undermine the natural capital on which long-term development depends. If forests are cleared for agriculture without sustainable management practices, soil erosion will accelerate, agricultural yields will decline over time, and the water regulation services that intact forests provide will be lost, increasing vulnerability to both floods and droughts. If industrial pollution is not regulated, it will impose health costs that will reduce worker productivity and will require expensive remediation that will ultimately exceed the short-term savings from avoiding regulation. If carbon-intensive development is chosen over cleaner alternatives, the country will lock itself into emissions-intensive infrastructure that will become increasingly costly as carbon pricing and clean technology costs evolve. The professor in the reading argues that this is not merely a theoretical concern — if we examine the historical experience of countries that pursued growth without environmental protection, we find that they paid substantial costs in degraded public health, depleted natural resources, and expensive cleanup that a more balanced approach would have avoided. She concludes that if countries frame environmental protection as a constraint on development rather than as an investment in its sustainability, they will make choices that trade long-term prosperity for short-term growth — and that if enough countries make this choice simultaneously, the global environmental consequences will impose costs on everyone.','hard'),
  (cid,76,272,'gap_fill','[TOEFL Speaking] If _____ reading''s _____ argument _____ (correct/prove), _____ policy _____ implications _____ (be) _____ profound: _____ governments _____ (need) to _____ (rethink) _____ fundamental _____ assumptions _____ (govern) _____ their _____ approach to _____ issue, and _____ (fail) to _____ (do) so _____ (risk) _____ (perpetuate) _____ precisely _____ conditions _____ (create) _____ problem in _____ first _____ place.','the / reading''s / proves correct / the / will be / profound / will need / rethink / the / fundamental / governing / their / the / failing / do / risks / perpetuating / precisely / the / that created / the / first',NULL,'Type 1 complex for policy implication summary.','hard'),

  -- BLOCK 77: TOEFL Writing — argumentação com Type 1
  (cid,77,273,'production','[TOEFL Writing — 200 words] Write a paragraph arguing that if current trends continue, a specific outcome will occur.','',NULL,'If current trends in urban population growth continue without commensurate investment in urban infrastructure and services, the cities that will house the majority of humanity by mid-century will be characterized by levels of congestion, pollution, and inequality that will undermine rather than enable human flourishing. The data are unambiguous: if the rate of urban expansion in low- and middle-income countries continues at its current pace, the gap between infrastructure supply and urban population will widen in ways that will make adequate housing, clean water, sanitation, and transportation increasingly inaccessible to the urban poor. If this gap is not addressed through substantially increased investment — both public and private — in the next decade, informal settlements will expand, existing infrastructure will deteriorate under the weight of demand that exceeds its design capacity, and the environmental consequences of unplanned urbanization will intensify. The consequences will not be confined to the urban poor: if cities become less functional, economic productivity will suffer, the quality of life of all urban residents will decline, and the political instability that often accompanies severe urban inequality will increase. The good news is that if governments prioritize urban planning and infrastructure investment now, the worst outcomes can be avoided — but this requires treating urban development as a strategic priority rather than allowing it to proceed as an unmanaged consequence of broader economic growth.','hard'),
  (cid,77,274,'production','[TOEFL Writing — 200 words] Write a paragraph on what will happen if digital connectivity continues to expand without adequate regulatory frameworks.','',NULL,'If digital connectivity continues to expand at its current pace without the development of adequate regulatory frameworks, the benefits of the digital economy will remain concentrated among those with the technical literacy, financial resources, and legal protections to access and use it safely, while the risks will be borne disproportionately by those least equipped to manage them. If data collection practices are not regulated to protect privacy, individuals will increasingly find that their personal information is used to manipulate their behavior in ways they have not consented to and cannot effectively resist. If platform monopolies are not subject to effective competition policy, the concentration of market power in a small number of technology companies will grow, reducing innovation and shifting the terms of the digital economy in ways that benefit shareholders at the expense of users and workers. If cybersecurity standards are not established and enforced, the increasing digitization of critical infrastructure will create vulnerabilities that will be exploited with potentially catastrophic consequences. If algorithmic systems are deployed without accountability mechanisms, biases embedded in training data will be systematically reproduced in consequential decisions about credit, employment, healthcare, and criminal justice. Each of these risks will intensify if regulatory development continues to lag technological change, and the longer the gap persists, the more difficult remediation will become.','hard'),

  -- BLOCK 78: TOEFL Writing — sínteses avançadas com Type 1
  (cid,78,275,'production','[TOEFL Writing — 200 words] Write a conclusion for an essay arguing that certain conditions must be met for a peace agreement to hold.','',NULL,'The analysis in this essay has demonstrated that a peace agreement will hold over the long term only if several conditions are simultaneously maintained, and that the failure of any one of them will jeopardize the stability of the whole. If the economic provisions of the agreement are not implemented in ways that deliver tangible improvements to the populations most affected by the conflict, spoilers will find a receptive audience for narratives that delegitimize the peace process. If transitional justice mechanisms are not established to address the grievances of victims, the unresolved wounds of the conflict will remain available for political mobilization. If security sector reform does not progress to the point where state institutions can provide reliable protection without replicating the abuses of the conflict period, trust in the state will remain insufficient to sustain the political compact on which peace depends. If regional and international actors do not maintain their engagement through the difficult early years of implementation, the political incentives to honor commitments will weaken precisely when honoring them is hardest. None of these conditions can be treated as secondary. If the parties and their international partners approach the agreement as a document to be managed rather than a commitment to be fulfilled, the agreement will become another casualty in a long list of peace processes that looked promising on paper but failed in practice.','hard'),
  (cid,78,276,'production','[TOEFL Writing — 200 words] Write a body paragraph arguing that free trade will benefit developing economies only if certain conditions are met.','',NULL,'Free trade will generate the development benefits that its advocates promise only if several conditions are met that are frequently absent in the agreements as actually negotiated. If developing country exporters are not given adequate time to build the productive capacity and the regulatory capacity needed to compete on open markets, trade liberalization will expose nascent industries to competition they cannot yet withstand, resulting in deindustrialization rather than the upgrading of productive capacity that development requires. If intellectual property rules are set at levels that reflect the interests of the major technology-exporting countries without adequate flexibility for developing countries to access essential medicines and technologies, the distributional consequences of trade agreements will be skewed against development needs. If labor and environmental standards are not included in trade agreements in ways that can be effectively enforced, a race to the bottom will occur in which developing countries are pressured to reduce protections to maintain competitiveness. If the gains from trade are not accompanied by adequate adjustment support for workers and communities displaced by import competition, the political backlash against trade liberalization will ultimately prevent the sustained openness that the theory requires. Trade can be a powerful engine of development, but only if it is governed by rules that reflect the development interests of all parties rather than primarily the export interests of the most powerful.','hard'),
  (cid,78,277,'gap_fill','If _____ (the/analysis/this essay) _____ (correct/prove), _____ implications for _____ policy _____ (be) _____ significant: _____ existing _____ approach _____ (not/sufficient/prove) and _____ more _____ fundamental _____ rethinking _____ (require/passive) if _____ stated _____ goals _____ (achieve/passive).','the analysis of this essay / proves correct / the / policy / will be / significant / the / existing / approach / will not prove sufficient / a / more / fundamental / will be required / the / stated / are to be achieved',NULL,'Complex Type 1 academic conclusion with passive and modal.','hard'),
  (cid,78,278,'gap_fill','Unless _____ international _____ community _____ (develop) _____ more _____ effective _____ mechanisms for _____ (share) _____ benefits of _____ technological _____ progress, _____ gap between _____ those who _____ (access) _____ frontier _____ technologies and those who _____ (not) _____ (widen) further, _____ (exacerbate) _____ already _____ severe _____ inequalities.','the / international / develops / more / effective / mechanisms / sharing / the / technological / the / those / access / frontier / do not / will widen / exacerbating / already / severe',NULL,'"Unless" + Type 1 for technology gap argument with participial consequence.','hard'),

  -- BLOCK 79: Exercícios finais — gap fill e produção
  (cid,79,279,'gap_fill','If _____ (the/right/conditions) _____ (put/passive) in _____ place now, _____ transition _____ (manage/passive) successfully and _____ (deliver) _____ gains that _____ (broadly/share/passive) — but if _____ (not), _____ costs _____ (concentrate) in _____ communities that _____ (already/least) _____ able to _____ (bear) them.','the right conditions / are put / place / the / will be managed / will deliver / will be broadly shared / if not / the / will concentrate / communities / are already least / bear',NULL,'Type 1 binary conditional for managed vs unmanaged transition.','hard'),
  (cid,79,280,'gap_fill','Should _____ evidence _____ (emerge) that _____ current _____ model _____ (not/fit) _____ data _____ (generate) by _____ new _____ observations, _____ scientific _____ community _____ (need) to _____ (revise) _____ theoretical _____ framework rather than _____ (dismiss) _____ anomalous _____ findings.','evidence / emerge / the / current / model / does not fit / the / generated / the / new / the / will need / revise / the / rather / dismiss / anomalous',NULL,'"Should" inversion + Type 1 for scientific paradigm revision.','hard'),
  (cid,79,281,'multiple_choice','[TOEFL Writing] Which Type 1 conditional is MOST EFFECTIVE in an academic essay conclusion?','If policymakers adopt the framework proposed in this analysis, the outcomes will be significantly more equitable than those produced by current approaches.','["If policymakers adopted the framework, the outcomes would be more equitable.","If policymakers had adopted the framework, the outcomes would have been more equitable.","If policymakers adopt the framework proposed in this analysis, the outcomes will be significantly more equitable than those produced by current approaches.","When policymakers adopt the framework, the outcomes are more equitable."]','Type 1 "adopt/will be" = real, achievable recommendation in essay conclusion. Type 2 would imply unlikely hypothetical.','medium'),
  (cid,79,282,'gap_fill','If _____ (this/analysis) _____ (correct/prove) and _____ projected _____ trajectory _____ (materialize), _____ institutions _____ (not/design/passive) to _____ (handle) _____ scale of _____ challenge _____ (face) _____ (increasingly/severe) _____ stress that _____ (eventually/force) _____ (either) _____ (reform) or _____ (collapse).','this analysis / proves correct / the / projected / materializes / institutions / not designed / handle / the / will face / increasingly severe / will eventually force / either / reform / collapse',NULL,'Type 1 complex conclusion with binary outcome.','hard'),
  (cid,79,283,'production','[TOEFL Writing — 200 words] Write a synthesis paragraph on what conditions will need to be met if the global economy is to remain stable.','',NULL,'The stability of the global economy over the coming decade will depend on whether several critical conditions are met simultaneously, and the failure of any one of them will create vulnerabilities that could trigger broader instability. If the major central banks manage the process of normalizing monetary policy without triggering a severe recession in debt-laden emerging economies, the global expansion will continue, albeit at a more moderate pace. If trade tensions between the major economies are managed through negotiation rather than escalating into protectionist spirals, supply chains will remain sufficiently integrated to support continued growth in productivity and living standards. If the transition to a low-carbon energy system proceeds at a pace that allows orderly adjustment of energy markets and avoids stranded asset crises in fossil fuel-dependent economies, the disruption of the energy transition will be manageable. If the financial system remains adequately regulated to prevent the accumulation of systemic risks of the kind that produced the 2008 crisis, the next decade will avoid the worst-case financial instability scenarios that current debt levels make possible. None of these conditions can be taken for granted, and the risks are compounded by the fact that an adverse shock in any one domain will increase vulnerability across all the others. If all of these conditions are met, the global economy will deliver continued, if uneven, progress; if several are not, the decade ahead could be significantly more turbulent than the one that preceded it.','hard'),
  (cid,79,284,'production','[TOEFL Writing — 200 words] Write a final paragraph on what will happen if international cooperation on climate change strengthens.','',NULL,'If international cooperation on climate change strengthens to the degree that the scientific evidence requires, the outcomes over the remainder of this century will be substantially better than current trajectories suggest. If the major emitters commit to and implement credible net-zero pathways, the most catastrophic warming scenarios will be avoided, and the adaptation challenge, while still substantial, will be manageable rather than overwhelming. If developed countries fulfill their financing commitments to developing nations, the latter will be able to pursue development trajectories that do not replicate the emissions-intensive path that high-income countries followed, and the global transition will proceed more rapidly and more equitably. If technology cooperation is deepened, the cost of clean energy will continue to fall, making the transition more economically attractive and reducing the political resistance that high transition costs generate. If carbon pricing and other policy mechanisms are coordinated internationally, carbon leakage will be minimized and the economic incentives for clean investment will be strengthened globally. The scenario in which all of these conditions are met is not guaranteed — the history of international climate negotiations is a history of commitments that have fallen short of what is needed. But it is achievable. And if it is achieved, the world will demonstrate that collective action on the defining challenge of our era is possible — which will itself be one of the most consequential outcomes of the decades of effort that will have made it possible.','hard'),
  (cid,79,285,'gap_fill','If _____ (the/reforms/proposed) _____ (implement/passive) _____ (comprehensively) and _____ (sustain/passive) through _____ multiple _____ political _____ cycles, _____ outcomes _____ (achieve/passive) _____ (substantially/exceed) those _____ (currently/project/passive) under _____ (the/status quo) _____ scenario.','the proposed reforms / are implemented / comprehensively / sustained / multiple / political / the / will be substantially exceeded / the / currently projected / the status quo',NULL,'Type 1 passive "implemented/sustained" + passive "will be exceeded" for reform outcome prediction.','hard'),
  (cid,79,286,'gap_fill','Only _____ if _____ (all/actors) _____ (treat) _____ agreement as _____ (genuine/commitment) rather than _____ (political/gesture) _____ (the/goals/agreement) _____ (achieve/passive) — and that _____ (require) _____ (a/kind/of) _____ political _____ will that _____ (historically/prove) _____ (difficult) to _____ (sustain).','Only / all / actors / treat / the / a / genuine commitment / political / will the goals of the agreement / be achieved / requires / a / kind / of / political / has historically proved / difficult / sustain',NULL,'"Only if" + Type 1 inversion + meta-political observation.','hard'),
  (cid,79,287,'gap_fill','If _____ (this/generation) _____ (rise) to _____ (meet) _____ challenge, _____ (those/come after) _____ (inherit) _____ world _____ (better/equip/passive) to _____ (provide) _____ security and _____ opportunity that _____ all _____ people _____ (deserve); if it _____ (not), _____ (they) _____ (face) _____ consequences of _____ failure to _____ (act).','this generation / rises / meet / the / those who come after / will inherit / a / better equipped / provide / the / the / deserve / does not / they / will face / the / failure / act',NULL,'Type 1 binary generational stakes conditional.','medium'),
  (cid,79,288,'production','[TOEFL Writing — 200 words] Final synthesis: write a conclusion on what the analysis has demonstrated about the role of institutions.','',NULL,'The analysis in this essay has demonstrated that if institutions are well-designed, adequately resourced, and embedded in political systems that provide genuine accountability, they will perform their functions effectively and will contribute to the public goods — security, rule of law, public health, environmental protection — that markets alone cannot provide. Conversely, if institutions are captured by the interests of powerful groups, starved of resources, or insulated from accountability, they will systematically fail the populations they are supposed to serve, and the consequences will be borne disproportionately by those with the least capacity to seek private alternatives. This conclusion may seem obvious, but it is remarkable how often it is ignored in practice: if institutional quality is treated as secondary to the design of formal policies, the best-designed policies will fail in implementation, and the resources invested in them will be wasted. If the lesson of this analysis is taken seriously, the policy implication is clear: if we want better outcomes, we need to invest in the institutional capacity, the accountability mechanisms, and the political conditions that allow institutions to work — not just in the policies that institutions are supposed to implement. If this investment is made, the record of successful institutional performance around the world demonstrates that good governance is achievable. If it is not, the gap between policy intent and policy outcome will persist, and the individuals and communities that depend on effective institutions will continue to bear the costs.','hard'),
  (cid,79,289,'gap_fill','If _____ (the/evidence/reviewed) in _____ (this/paper) _____ (correctly/interpret/passive), _____ conclusion _____ (inescapable/be) that _____ current _____ approaches _____ (not/sufficient/prove) and that _____ (more/fundamental/change) _____ (require/passive) — _____ (the/only/question) _____ (be) whether _____ (it) _____ (achieve/passive) proactively or _____ (impose/passive) by _____ circumstances.','the evidence reviewed / this paper / is correctly interpreted / the / will be inescapable / the / will not prove sufficient / more fundamental change / will be required / the / is / it / will be achieved / imposed / circumstances',NULL,'Type 1 complex academic conclusion with passive chain.','hard'),
  (cid,79,290,'gap_fill','Should _____ (the/conditions) _____ (describe/passive) in _____ (this/analysis) _____ (materialize), _____ (we) _____ (witness) _____ (a/transition) of _____ historical _____ significance — one that _____ (compare/passive) in _____ scope and _____ consequence to _____ (the/greatest) _____ transformations of _____ previous _____ centuries.','the conditions / described / this analysis / materialize / we will witness / a / transition / historical / will be compared / scope / consequence / the greatest / the / previous',NULL,'"Should" inversion + Type 1 for historical significance of conditional transition.','hard'),
  (cid,79,291,'gap_fill','If _____ (the/lessons) of _____ (this/experience) _____ (learn/passive) and _____ (apply/passive) to _____ future _____ situations, _____ (they) _____ (serve) _____ (a/valuable) _____ (function) — but if _____ (they) _____ (not/absorb/passive), _____ (we) _____ (risk) _____ (repeat) _____ (the/same) _____ mistakes that _____ (produce) _____ (the/crisis) in _____ first _____ place.','the lessons / this experience / are learned / applied / to / future / they will serve / a / valuable / function / they / are not absorbed / we / risk / repeating / the same / produced / the crisis / the / first',NULL,'Type 1 binary "if learned/if not absorbed" for lessons-learned argument.','hard'),
  (cid,79,292,'production','[TOEFL Writing — Final 200 words] Write a capstone conclusion using Type 1 conditionals throughout.','',NULL,'If the arguments developed in this essay are accepted, the policy implications are clear and the urgency is evident. If governments act now — while the costs of action are still manageable and before irreversible thresholds are crossed — the outcomes over the remainder of the century will be substantially better than current trajectories suggest. If they delay, the window for orderly, cost-effective transition will narrow and ultimately close, and the disruption of an unmanaged transition will prove far more costly in human, economic, and environmental terms than the investment in proactive action requires. If the international community coordinates its response — sharing technology, mobilizing finance, and aligning regulatory frameworks — the collective action problems that have historically prevented adequate progress will be overcome, and the global public goods that individual actors cannot provide for themselves will be secured. If civil society, business, and government align their efforts around the shared goal of sustainable development, the political will required for the necessary scale of action will be generated and sustained through the electoral and business cycles that have historically undermined long-term commitments. None of these conditions will be met automatically. Each requires deliberate choices, sustained effort, and the kind of leadership that treats the long-term interest as a genuine political priority. But if that leadership emerges — and the evidence of recent years suggests it can — the future that becomes possible is worth the effort required to reach it.','hard'),
  (cid,79,293,'gap_fill','If _____ (the/current/generation) _____ (succeed) where _____ (previous/ones) _____ (fall/short), it _____ (be) because _____ (it) _____ (choose) to _____ (act) on _____ (the/best/evidence) available rather than _____ (allow) _____ (the/urgency) of _____ (the/short/term) to _____ (crowd out) _____ (the/imperative) of _____ (the/long).','the current generation / succeeds / previous ones / have fallen short / will be / it / chose / act / the best evidence / allowing / the urgency / the short term / crowd out / the imperative / the long',NULL,'Type 1 future consequential + past simple contrast for generational agency argument.','hard'),
  (cid,79,294,'gap_fill','Ultimately, if _____ (the/vision) _____ (set out) in _____ (this/framework) _____ (realize/passive), _____ (it) _____ (be) through _____ (the/combined) _____ efforts of _____ (countless/actors) _____ (work) toward _____ (a/shared) _____ goal — _____ (this/is) _____ (the/nature) of _____ (the/kind/of) _____ transformative _____ change that _____ (analysis/of/this/kind) _____ (seek) to _____ (both/describe/and/enable).','the vision / set out / this framework / is realized / it / will be / through / the combined / efforts / countless actors / working / a / shared / this is / the nature / the kind of / transformative / this kind of analysis / seeks / both describe and enable',NULL,'Type 1 passive "is realized" + "will be" for transformative vision conditional.','hard'),
  (cid,79,295,'gap_fill','If _____ (we) _____ (take) _____ (the/evidence) seriously, _____ (there) _____ (be) _____ (a/clear) _____ path forward — difficult, _____ (perhaps), but _____ (achievable). If _____ (we) _____ (not), _____ (the/consequences) _____ (speak) for _____ (themselves).','we / take / the evidence / there / will be / a / clear / difficult / perhaps / achievable / we do not / the consequences / will speak / themselves',NULL,'Simple binary Type 1 for emphatic conclusion.','medium'),
  (cid,79,296,'gap_fill','If _____ (the/right/investments) _____ (make/passive) now in _____ (the/institutions), _____ (the/human/capital), and _____ (the/physical/infrastructure) that _____ (the/transition) _____ (require), _____ (the/returns) _____ (prove) _____ (substantial) — not merely in _____ (economic/terms) but in _____ (the/quality) of _____ (life) and _____ (the/resilience) of _____ (the/communities) that _____ (depend) on _____ (them).','the right investments / are made / the institutions / the human capital / the physical infrastructure / the transition / requires / the returns / will prove / substantial / economic terms / the quality / life / the resilience / the communities / depend / them',NULL,'Type 1 passive investment conditional with multi-domain returns.','hard'),
  (cid,79,297,'gap_fill','Should _____ (the/partnership) _____ (prove) as _____ (transformative) as _____ (its/architects) _____ (envision), _____ (it) _____ (stand) as _____ (a/model) for _____ (the/kind/of) _____ (cooperation) that _____ (the/challenges) of _____ (the/century) _____ (demand).','the partnership / prove / transformative / its architects / envision / it / will stand / a / model / the kind of / cooperation / the challenges / the century / demand',NULL,'"Should" inversion + Type 1 for transformative partnership conditional.','medium'),
  (cid,79,298,'gap_fill','If _____ (these/conditions) _____ (meet/passive), _____ (the/future) _____ (look) _____ (significantly) _____ (more/promising) than _____ (current/trajectories) _____ (suggest); if _____ (they) _____ (not), _____ (the/challenge) _____ (prove) _____ (more/formidable) than _____ (any/single/actor) _____ (address) _____ (alone).','these conditions / are met / the future / will look / significantly / more promising / current trajectories / suggest / they are not / the challenge / will prove / more formidable / any single actor / can address / alone',NULL,'Binary Type 1 conditional for optimistic vs pessimistic outcome.','medium'),
  (cid,79,299,'production','[TOEFL Writing — 200 words] Write an introduction for an essay arguing that if global governance reforms are made, international cooperation will improve.','',NULL,'If the right reforms to global governance institutions are implemented in the coming decade, the capacity of the international community to address the shared challenges that no single nation can manage alone will improve substantially. This proposition — that better institutions will produce better outcomes — may seem straightforward, but it is contested by those who argue that the obstacles to effective international cooperation are too deeply rooted in the competitive interests of sovereign states for institutional reform to make a meaningful difference. This essay will argue that this pessimistic view, while understandable given the disappointments of recent decades, underestimates the degree to which institutional design shapes behavior and the degree to which well-designed institutions can alter the incentive structures that lead states to defect from cooperative arrangements. If the Security Council''s composition is reformed to reflect the current distribution of global power, its decisions will command greater legitimacy, making compliance more likely. If the WTO''s dispute settlement mechanism is restored to full functionality, the rules-based trading system will be more effectively enforced. If climate finance commitments are honored and new mechanisms are established to mobilize private capital for the green transition, the engagement of developing countries in global climate efforts will strengthen. The essay proceeds in three parts, examining each of these institutional reform priorities in turn before drawing conclusions about the conditions under which progress is achievable.','hard'),
  (cid,79,300,'production','[TOEFL Writing — Final capstone] Write a concluding paragraph synthesizing the essay''s conditional argument about global cooperation.','',NULL,'The argument developed in this essay has been conditional throughout, and appropriately so: the future of international cooperation is genuinely contingent, not determined. If the conditions this analysis has identified as necessary are met — genuine commitment by major powers to rules-based multilateralism, adequate reform of institutions to reflect the current distribution of global influence, sustained financing of global public goods, and the development of new governance frameworks adequate to the digital age — the international community will prove capable of managing the challenges that the twenty-first century is generating. If these conditions are not met, the alternative is not catastrophe in all domains but the kind of muddling through in which shared problems are incompletely addressed, costs that could be shared are borne by the most vulnerable, and opportunities that require coordination to realize are foregone. The difference between these outcomes will not be determined by impersonal historical forces but by choices — choices about whether to invest in institutional capacity, choices about whether to honor commitments, choices about whether to treat the long-term collective interest as a genuine political priority. If leaders in the major powers make those choices well, the institutional framework will improve; if they do not, it will weaken. This essay cannot determine which of these scenarios will occur — that depends on decisions not yet made by actors not yet in office. What it can do is specify, as clearly as the evidence allows, what is at stake and what will need to be true if the more hopeful scenario is to be realized.','hard')

